const getMockState = () => {
  const state = globalThis.__PUPPETS_COPILOT_MOCK__;
  if (!state) throw new Error('Puppets Copilot mock state is not configured.');
  return state;
};

const normalizeResponse = response => {
  if (response instanceof Error) throw response;
  if (response && typeof response === 'object' && 'error' in response) {
    throw new Error(String(response.error));
  }
  if (typeof response === 'string') return response;
  return JSON.stringify(response);
};

export class CopilotClient {
  constructor(options) {
    this.options = options;
    this.state = getMockState();
    this.state.calls.push({ type: 'construct', options });
  }

  async start() {
    this.state.calls.push({ type: 'start' });
  }

  async createSession(config) {
    this.state.calls.push({ type: 'createSession', config });
    return {
      sendAndWait: async ({ prompt }, timeout) => {
        this.state.calls.push({
          type: 'sendAndWait',
          prompt,
          systemPrompt: config?.systemMessage?.content || '',
          model: config?.model || null,
          timeout,
        });
        if (!this.state.responses.length) {
          throw new Error('Unexpected Copilot SDK call with no queued mock response.');
        }
        return {
          data: {
            content: normalizeResponse(this.state.responses.shift()),
          },
        };
      },
      disconnect: async () => {
        this.state.calls.push({ type: 'disconnect' });
      },
    };
  }

  async stop() {
    this.state.calls.push({ type: 'stop' });
    return [];
  }
}
